/**
 * Shared column helpers for every schema file.
 *
 * Conventions (see docs/CONVENTIONS.md → "Database"):
 *  - The Drizzle client and drizzle-kit both use `casing: "snake_case"`, so write
 *    camelCase property names WITHOUT explicit column names: `firstName: text()`.
 *  - Primary keys are UUIDs generated by PostgreSQL (`gen_random_uuid()`).
 *  - All timestamps are `timestamptz`.
 *  - Money is stored as integer minor units (`bigint`) next to an ISO-4217 currency code.
 *    Never assume a currency (no hardcoded INR).
 *  - Status / type columns are `text` with a TS enum (no Postgres enums → painless migrations).
 */
import { sql } from "drizzle-orm";
import { bigint, char, timestamp, uuid } from "drizzle-orm/pg-core";

/** UUID primary key with database default. */
export const pk = () => uuid().primaryKey().defaultRandom();

/** timestamptz column (nullable unless chained with .notNull()). */
export const tstz = () => timestamp({ withTimezone: true, mode: "date" });

/** created_at / updated_at pair. Spread into a table: `...timestamps`. */
export const timestamps = {
  createdAt: timestamp({ withTimezone: true, mode: "date" }).notNull().defaultNow(),
  updatedAt: timestamp({ withTimezone: true, mode: "date" })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

/** created_at only (append-only tables). */
export const createdAtOnly = {
  createdAt: timestamp({ withTimezone: true, mode: "date" }).notNull().defaultNow(),
};

/** Money amount in minor units (paise, cents, fils...). Pair with currencyCode(). */
export const moneyMinor = () => bigint({ mode: "number" });

/** ISO-4217 currency code. */
export const currencyCode = () => char({ length: 3 });

/** ISO-3166-1 alpha-2 country code. */
export const countryCode = () => char({ length: 2 });

/** Empty JSON object default for jsonb columns. */
export const emptyJsonObject = sql`'{}'::jsonb`;
/** Empty JSON array default for jsonb columns. */
export const emptyJsonArray = sql`'[]'::jsonb`;
/** Empty text[] default. */
export const emptyTextArray = sql`'{}'::text[]`;
